let requestVersion = 0;
async function search(query) {
  const version = ++requestVersion;
  const results = await fetch(`/api/tasks?q=${encodeURIComponent(query)}`).then(r => r.json());
  if (version !== requestVersion) return;
  render(results);
}

function totalOpen(tasks) {
  console.assert(Array.isArray(tasks), "tasks must be an array");
  debugger;
  return tasks.filter(task => !task.done).length;
}
console.log(totalOpen([{ done: false }, { done: true }]));

const state = { tasks: [], filter: "ALL", search: "" };
function visibleTasks() {
  return state.tasks.filter(task => {
    const statusOk = state.filter === "ALL" || (state.filter === "DONE") === task.done;
    const searchOk = task.title.toLowerCase().includes(state.search.toLowerCase());
    return statusOk && searchOk;
  });
}
